# Équipement propre à chaque plante, et reprise des anciennes inspections
# parasites : le parasite unique devient une liste (le champ accepte désormais
# plusieurs parasites et la saisie libre), et le traitement, qui a maintenant sa
# propre action, est recopié dans le commentaire de l'entrée pour ne rien perdre.

from django.db import migrations, models


OLD_TREATMENT_LABELS = {
    'MANUAL': 'Retrait manuel',
    'BLACK_SOAP': 'Savon noir',
    'NEEM': 'Huile de neem',
    'ALCOHOL': 'Alcool',
    'INSECTICIDE': 'Insecticide',
}


def convert_pest_checks(apps, schema_editor):
    PlantHistory = apps.get_model('Plantes', 'PlantHistory')

    entries = (PlantHistory.objects
               .filter(action__code='CHECK_PESTS')
               .exclude(detail=None))

    for entry in entries:
        detail = dict(entry.detail)

        if 'pest' not in detail and 'treatment' not in detail:
            continue

        pest = detail.pop('pest', None)
        if pest:
            detail['pests'] = ['Autre'] if pest == 'OTHER' else [pest]

        treatment = detail.pop('treatment', None)
        if treatment and treatment != 'NONE':
            note = f'Traitement : {OLD_TREATMENT_LABELS.get(treatment, treatment)}'
            entry.comment = f'{entry.comment}\n{note}' if entry.comment else note

        entry.detail = detail or None
        entry.save(update_fields=['detail', 'comment'])


